perl -e '
use strict; use warnings;
my $repo = "/bench/repo";
my @entities = qw(
  User Memo Attachment Reaction Inbox IdentityProvider InstanceSetting
  MemoRelation MemoShare UserIdentity UserSetting
  RowStatus Visibility Role
);

sub pkg_of {
  my ($file) = @_;
  $file =~ s|^\Q$repo/||;
  return "store" if $file =~ m|^store/|;
  if ($file =~ m|^(.*?)/[^/]+\.go$|) {
    my $dir = $1;
    $dir =~ s|/|.|g;
    return $dir;
  }
  return $file;
}

for my $type (@entities) {
  my @lines = qx{grep -r --include="*.go" -n "store\\.$type\\b" $repo 2>/dev/null};
  my %pkgs;
  for my $line (@lines) {
    chomp $line;
    my ($file) = split /:/, $line, 2;
    next if $file =~ /_test\.go$/;
    next if $file =~ m|^$repo/store/|;
    my $pkg = pkg_of($file);
    $pkgs{$pkg} = 1;
  }
  printf "%2d %s\n", scalar(keys %pkgs), $type;
}
' | sort -rn

